#!/usr/bin/env python3
"""Build the complete approved real-image gallery and concise agent case files."""
from __future__ import annotations
import html
import json
from pathlib import Path
import shutil
from build_motion import build_page

ROOT=Path(__file__).resolve().parents[1]
SKILL=ROOT/'skills/mechanism-figures'
E=html.escape


def case_text(r):
    t,s=r['transfer'],r['visual_style']
    lines=['# '+r['label']+' — '+t['move'],'',r['authors']+' · '+r['venue']+' '+str(r['year'])+' · '+r['display_figure'],'','[Publication]('+r['source']+') · [Original image source]('+r['imageSource']+')','','## Inspect the actual images before designing','']
    for a in r['assets']:
        lines.append('- ['+a['kind']+' figure](../../'+a['path']+') — SHA-256 `'+a['sha256']+'`. '+a['treatment'])
    lines+=['','Reading a caption or this guide is not image inspection. Open at least two approved reference images at readable size and record their hashes.','','**Use when:** '+t['when'],'','## See the mechanism','']
    lines += [str(i+1)+'. '+x for i,x in enumerate(t['trace'])]
    for name,key in [('Mechanism','mechanism'),('Visual construction','construction'),('What the eye understands','eye'),('Why an ordinary plot is weaker','stronger')]:
        lines+=['','**'+name+':** '+r[key]]
    lines+=['','## Learn this visual style, then adapt it','','**Observe:** '+s['observed'],'','**Apply:** '+s['apply'],'','Record `composition_observation`, `encoding_observation`, `style_observation`, and `planned_application` for this image. Specify visible layout, persistent geometry, selective emphasis, annotation placement, color roles and whitespace—not just “clean” or “beautiful”.','','## Transfer into the project','','**Replace the objects:** '+t['map'],'','**Keep the relationship:** '+t['keep'],'']
    lines += [str(i+1)+'. '+x for i,x in enumerate(t['build'])]
    lines+=['','**Acceptance test:** '+t['check'],'','**Do not copy literally:** '+t['avoid'],'','**Scientific boundary:** '+r['limit'],'','## Attribution and rights','',r['commentary_origin'],'','Original authors/publishers retain image rights. The repository MIT license covers code/commentary, not the figures. '+r['rights']['note']]
    if r['rights'].get('license_url'):lines+=['','['+r['rights']['license']+']('+r['rights']['license_url']+')']
    return '\n'.join(lines).rstrip()+'\n'


def build():
    data=json.loads((SKILL/'assets/calibration.json').read_text())
    canon=json.loads((SKILL/'assets/approved-canon.json').read_text())
    refs=data['references']
    if [r['id'] for r in refs]!=canon['approved_ids']:raise ValueError('Current curated selection/order changed')
    if any(not r['assets'] or not r['display_assets'] for r in refs):raise ValueError('All approved references must contain real visible images')
    index=['# Approved published-figure calibration','','All 20 current references have actual images included. Eight were replaced after the user’s explicit October 2026 feedback. No self-generated examples set the standard.','','**Every figure task:** inspect at least two real reference images, record their image hashes and specific composition/encoding/style observations, and compare the rendered result against them before passing review.','','| Reference | Explanatory construction | Group |','|---|---|---|']
    credits=['# Published reference figures: attribution and rights','','This is the current twenty-reference gallery. Eight user-retired references were replaced on 2026-10-08; the other twelve and their image bytes are unchanged. All scientific reference images are published figures or identified panels, not generated replacements. Current anchor order and retired IDs are recorded in assets/approved-canon.json; replacements are curator selections responding to the user’s request, not retroactively labeled as previously approved.','','The MIT license applies to original code and editorial commentary only. **Published figures are third-party material and are not relicensed under MIT.** They are included with source-specific critical discussion. Inclusion here does not grant general image-reuse or further republication rights. Verified licenses, unverified reuse terms, original sources and modifications remain explicit for each item. Do not infer permission from a public URL, from inclusion, or from the code license.','','`bundled` identifies previously verified CC BY assets; `reference-excerpt` identifies approved figures included for critical reference study without claiming a general image license. The distinction is about recorded rights, not whether an image is displayed.','','Further users are responsible for checking the applicable source-specific permissions and image credit exceptions for their intended use. Original authors do not endorse this skill.','']
    groups={'structure':'Geometry & structure','transformation':'Transformations','dynamics':'Dynamics','evidence':'Evidence & history','invariance':'Identity & invariance','contrast':'Counterfactuals & repair'}
    cards=[]
    for n,r in enumerate(refs,1):
        t,s=r['transfer'],r['visual_style']
        (SKILL/'references/cases'/(r['id']+'.md')).write_text(case_text(r))
        index.append('| ['+r['label']+'](cases/'+r['id']+'.md) | '+t['move']+' | '+groups[t['group']]+' |')
        assets={a['path']:a for a in r['assets']}
        focus=[assets[p] for p in r['display_assets']]
        media='<div class="image-stage'+(' '+r.get('display_layout','paired') if len(focus)>1 else '')+'">'+''.join('<button type="button" class="image-button" data-open="'+r['id']+'" aria-label="Inspect '+E(r['label'])+' at full size"><img src="'+E(a['path'].replace('assets/','',1))+'" alt="'+E(r['label']+' — '+r['display_figure']+'. '+r['look'])+'" loading="'+('eager' if n==1 else 'lazy')+'" decoding="async">'+('<span class="published-panel-label">'+E(a['label'])+'</span>' if a.get('label') else '')+'</button>' for a in focus)+'</div>'
        chain='<div class="chain">'+''.join('<div><h3>'+name+'</h3><p>'+E(r[key])+'</p></div>' for name,key in [('Mechanism','mechanism'),('Visual construction','construction'),('The eye understands','eye'),('Why this is stronger','stronger')])+'</div>'
        choices=''.join('<button type="button" class="asset-link" data-open="'+r['id']+'" data-asset="'+E(a['path'])+'">'+E(('Related published figure' if a['kind']=='related' else a['kind'].capitalize()+' figure'))+' ↗</button>' for a in r['assets'])
        credits+=['## '+r['label'],'',r['authors']+'. *'+r['paper']+'*. '+r['venue']+' ('+str(r['year'])+'), '+r['display_figure']+'.','','[Publication]('+r['source']+') · [Original figure source]('+r['imageSource']+') · [Recorded permission basis]('+r['rights']['basis_url']+')','','**'+r['rights']['status']+'** — '+r['rights']['note'],'']
        if r['rights'].get('license_url'):credits+=['['+r['rights']['license']+']('+r['rights']['license_url']+')','']
        for a in r['assets']:credits+=['- `'+a['path']+'` — '+a['treatment']+' SHA-256: `'+a['sha256']+'`.']
        credits+=['']
        cards.append('<article id="'+r['id']+'" data-group="'+t['group']+'"><header class="ref-head"><div><p class="meta">'+str(n).zfill(2)+' · '+E(r['venue'])+' · '+str(r['year'])+'</p><h2>'+E(r['label'])+'</h2><p class="fig-name">'+E(r['display_figure'])+' · '+E(t['move'])+'</p></div><button type="button" class="quiet" data-open="'+r['id']+'">Inspect full-size figure ↗</button></header>'+media+'<div class="reading"><b>Look here</b><ol>'+''.join('<li>'+E(x)+'</li>' for x in t['trace'])+'</ol></div>'+chain+'<div class="style-lesson"><h3>What the agent must learn from this style</h3><p>'+E(s['observed'])+'</p><p><strong>In your project:</strong> '+E(s['apply'])+'</p></div><details class="recipe"><summary>Apply this construction in another scientific project</summary><p><strong>Map the objects.</strong> '+E(t['map'])+'</p><p><strong>Keep the relationship.</strong> '+E(t['keep'])+'</p><ol>'+''.join('<li>'+E(x)+'</li>' for x in t['build'])+'</ol><p><strong>Acceptance test.</strong> '+E(t['check'])+'</p><p><strong>Do not copy literally.</strong> '+E(t['avoid'])+'</p></details><p class="boundary"><strong>Scientific boundary.</strong> '+E(r['limit'])+'</p><footer><p>'+E(r['authors'])+' · <a href="'+E(r['source'])+'" target="_blank" rel="noopener noreferrer">'+E(r['paper'])+' ↗</a></p><div class="source-links">'+choices+'<a href="'+E(r['imageSource'])+'" target="_blank" rel="noopener noreferrer">Original source ↗</a><a href="../references/cases/'+r['id']+'.md">Agent reading ↗</a></div><details class="credits"><summary>Attribution, figure treatment and rights</summary><p>'+E(r['rights']['note'])+'</p><p>'+E(' '.join(a['treatment'] for a in r['assets']))+'</p><a href="'+E(r['rights']['basis_url'])+'" target="_blank" rel="noopener noreferrer">Source terms ↗</a>'+(' · <a href="'+E(r['rights']['license_url'])+'">'+E(r['rights']['license'])+'</a>' if r['rights'].get('license_url') else '')+'</details></footer></article>')
    (SKILL/'references/calibration-index.md').write_text('\n'.join(index)+'\n')
    third='\n'.join(credits).rstrip()+'\n'
    (ROOT/'THIRD_PARTY.md').write_text(third);(SKILL/'THIRD_PARTY.md').write_text(third)
    shutil.copyfile(ROOT/'LICENSE',SKILL/'LICENSE')
    filters='<button type="button" data-filter="all" aria-pressed="true">All 20</button>'+''.join('<button type="button" data-filter="'+k+'" aria-pressed="false">'+v+'</button>' for k,v in groups.items())
    motion_markup,motion_css,motion_js=build_page(refs)
    content='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="description" content="Twenty curated real published mechanism-revealing figures, with visual readings and mandatory agent style calibration."><title>MechanismFigures — curated published reference gallery</title><style>'+(ROOT/'tools/gallery.css').read_text()+'\n'+motion_css+'</style></head><body><a class="skip" href="#gallery">Skip to reference figures</a><main><header class="intro"><p class="meta">MechanismFigures · curated published references</p><h1>Learn from the real figures.</h1><p class="lead">The current curated gallery: <strong>20 published references, 29 original figure assets.</strong> Eight stronger replacement constructions; no self-generated substitutes. See the mechanism, study the composition, and adapt the visual construction to your own science.</p><div class="top-links"><a href="#how-it-works">Watch how it works</a><a href="https://github.com/KumarNavish/MechanismFigures/blob/main/docs/INSTALL.md">Install globally</a><a href="../SKILL.md">Skill workflow</a><a href="../references/style-calibration.md">Required visual calibration</a><a href="https://github.com/KumarNavish/MechanismFigures/releases/latest">Installable skill</a></div></header>'+motion_markup+'<section class="filter-bar" aria-label="Find a reference"><nav aria-label="Mechanism families">'+filters+'</nav><div class="search-row"><label for="search">Find a reference or visual operation</label><input id="search" type="search" placeholder="e.g. GraphCast, feedback, correspondence…"><span id="count" role="status">20 of 20 references</span></div></section><section id="gallery">'+''.join(cards)+'</section><p id="empty" hidden>No matches. Try a scientific object, reference title or visual operation.</p><section class="agent-rule"><h2>Every agent starts here.</h2><p>Before drawing, open at least two of these actual images. Record what you see in their composition, geometry, annotation, color roles and whitespace. Map those choices onto your project. Before finishing, compare the rendered result back against the same references—not against a self-generated example or a generic diagram template.</p><p><a href="../references/style-calibration.md">Read the operational calibration protocol ↗</a></p></section><footer class="page-footer"><p>Actual published figures and identified panels only. Editorial readings explain what to see and how to transfer it; they are not an endorsement by the original authors. Figures retain their author/publisher rights and are not covered by the repository’s MIT license. <a href="../THIRD_PARTY.md">Full attribution and permissions record</a>.</p><p>MechanismFigures 0.4.0 · Complete approved canon · guided motion walkthrough.</p></footer></main><dialog id="viewer" aria-labelledby="viewer-title"><div class="viewer-bar"><strong id="viewer-title"></strong><button type="button" id="fit" aria-pressed="false">Native size</button><button type="button" id="close">Close ×</button></div><div id="viewer-choices"></div><div id="viewer-images"></div><p id="viewer-credit"></p></dialog><script id="calibration-data" type="application/json">'+json.dumps({'version':'0.4.0','references':refs},ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+(ROOT/'tools/gallery.js').read_text()+'</script><script>'+motion_js+'</script></body></html>'
    (SKILL/'assets/gallery.html').write_text(content)
    print(json.dumps({'references':len(refs),'images':sum(len(r['assets']) for r in refs),'displayed_image_panels':sum(len(r['display_assets']) for r in refs),'primary_six':[r['id'] for r in refs[:6]],'generated_reference_images':0,'gallery_bytes':len(content.encode())}))


if __name__=='__main__':build()
